"""
Other ops
"""
import os
import time
import datetime
from taf.ul.trs_e2e_fw.lib.global_vars import global_vars
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable
from taf.ul.trs_e2e_fw.lib.oam.mzoam.mzoam_base import MzoamBaseClass

logger = BackgroundLogger.Instance()


class OtherOps(MzoamBaseClass):
    """
    Other ops
    """
    def __init__(self):
        super(OtherOps, self).__init__()

    def collect_snapshot(self, **kwargs):
        """ This function collects snapshot and saves in a file in execution_logs
            location:  LOCAL|SBTS|SERVER
            type:  ( 0: All| 1: Crash & recovery| 2: 5G User and Control Plane|
                     3: 5G Control Plane| 4: HW and SW configuration| 5: RU only )
            coverage: ( 0: Full | 1: Normal | 2: Minor )
            rap:
            vnf: (on|off)
            request_id
            protocol
            username
            password
            ipaddr
            port
            target_path
            snapshot_path
            timeout
            alias
        """
        location = kwargs.pop('location', 'LOCAL')
        type_ = kwargs.pop('type', '0')
        coverage = kwargs.pop('coverage', '0')
        rap = kwargs.pop('rap', "['RAP1, RAP2']")
        vnf = kwargs.pop('vnf', "on")
        request_id = kwargs.pop('request_id', "0000")
        timeout = kwargs.pop('timeout', 480)
        alias = kwargs.pop('alias', 'default')
        target_file = None
        server_details = {}

        if location.lower() == 'local':
            tstamp = time.time()
            tstamp = datetime.datetime.fromtimestamp(tstamp).strftime('%d%m%y_%H%M%S')
            target_file = 'execution_logs/{}'.format('snapshot_{}.{}'.format(tstamp, 'zip'))
            logger.debug("target file :: {}".format(target_file))
            if not os.path.exists(os.path.dirname(target_file)):
                os.makedirs(os.path.dirname(target_file))
        elif location.lower() == 'server':
            log_server = kwargs.get('log_server_name')
            server_details = get_config_variable([log_server])

        self.mzom_client.make_snapshot(save_location=location, snapshot_path=target_file,
                                       type=type_, level=coverage, rap=rap, vnf=vnf,
                                       request_id=request_id, timeout=timeout, session=alias,
                                       **server_details)
        return target_file
